import type { TSESLint } from '@typescript-eslint/utils';

/**
 * Markers by which a file DECLARES itself machine-generated.
 *
 * This is evidence, not name inference. The distinction matters and it is the
 * one `CLAUDE.md` puts first: `filename.includes('generated')` is a guess about
 * a spelling that a stranger's `src/generated-reports/` defeats, while a header
 * saying "Do not edit the class manually" is a statement by whoever produced
 * the file. We read the statement.
 *
 * The list is closed and comes from the conventions tools already agree on —
 * the same set GitHub Linguist checks when it collapses a diff:
 *
 * - `@generated` — the Facebook/Meta docblock annotation.
 * - `Code generated by … DO NOT EDIT.` — the Go convention, `go generate`.
 * - `This code was generated by` — OpenAPI Generator, which is what emits
 *   twilio-node's entire `src/rest/**` tree.
 * - `auto generated` / `autogenerated` / `automatically generated` — protoc,
 *   swagger-codegen, Prisma, GraphQL Codegen and most of the long tail.
 *
 * One alternation rather than a literal list fed to `.some(m => text.includes(m))`:
 * that shape is what `lint:name-inference` flags, and rightly — it is
 * indistinguishable at the AST from word-matching an identifier. The haystack
 * here is a comment rather than a name, but the honest fix is to not write the
 * shape, not to register an exception for it.
 *
 * Deliberately NOT a marker on its own: "Do not edit". Hand-written files carry
 * that instruction too — a checked-in lockfile shim, a vendored patch — and it
 * says nothing about who wrote the code.
 */
const GENERATED_BANNER =
  /@generated\b|(?:code|this code|this file) was generated by|code generated by|auto-?generated|automatically generated/i;

/**
 * How far into the file a generation banner is allowed to sit.
 *
 * A banner is a header. Scanning the whole file would let the phrase "this code
 * was generated by hand" inside a function body silence a rule for the entire
 * module, which is a suppression an attacker — or a careless comment — gets for
 * free. Bounding it to the leading comment block keeps the marker something the
 * file states about ITSELF.
 */
function leadingComments(
  sourceCode: Readonly<TSESLint.SourceCode>,
): readonly { value: string }[] {
  const comments = sourceCode.getAllComments();
  const firstToken = sourceCode.getFirstToken(sourceCode.ast, {
    includeComments: false,
  });
  // A file that is nothing but comments has no token to stop at, so every
  // comment in it is leading.
  if (!firstToken) return comments;
  const start = firstToken.range[0];
  return comments.filter((comment) => comment.range[1] <= start);
}

/**
 * Does this file declare itself machine-generated?
 *
 * Rules about maintainability — duplication, complexity, parameter counts —
 * are advice to a person who edits the file. Nobody edits generated code; it is
 * rewritten wholesale on the next run of the generator. A correct finding that
 * nobody can act on still costs the rule's credibility, which is the effective
 * false-positive standard this repo measures against.
 *
 * Security rules are the opposite case and must NOT use this: generated code
 * ships and runs, so an injection in it is a live vulnerability whoever typed
 * it. This predicate is for maintainability advice only.
 */
export function isGeneratedFile(
  sourceCode: Readonly<TSESLint.SourceCode>,
): boolean {
  for (const comment of leadingComments(sourceCode)) {
    if (GENERATED_BANNER.test(comment.value)) return true;
  }
  return false;
}
